begin;
create function pg_temp.check_stress(ok boolean,msg text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception '%',msg;end if;raise notice 'PASS: %',msg;end$$;
create function pg_temp.expect_stress(stmt text,code text,msg text) returns void language plpgsql as $$begin begin execute stmt;exception when others then if sqlstate=code then raise notice 'PASS: %',msg;return;else raise;end if;end;raise exception 'Expected failure: %',msg;end$$;
insert into auth.users(id,email_confirmed_at) values('60030000-0000-4000-8000-000000000001',now());
insert into public.properties values('hu60-stress-p','60030000-0000-4000-8000-000000000001','{"investment":{"stress":[{"name":"Conservador"}]}}','2026-10-11T00:00:00Z');
select pg_temp.check_stress(not has_function_privilege('authenticated','public.stress_computed_scenario(uuid,text,timestamptz,timestamptz,text,uuid,integer,jsonb)','execute') and not has_function_privilege('anon','public.stress_computed_scenario(uuid,text,timestamptz,timestamptz,text,uuid,integer,jsonb)','execute'),'only server may submit computed snapshots');
set local role service_role;
select public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-11T00:00:00Z',null,'First','60030000-0000-4000-8000-000000000010',0,'{"property":{"id":"hu60-stress-p"},"sourceStress":{"name":"Conservador"},"engine":"test","result":{"profit":100}}');
select pg_temp.check_stress((public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-11T00:00:00Z',null,'First','60030000-0000-4000-8000-000000000010',0)->>'replayed')::boolean,'receipt lookup without recalculation');
select pg_temp.expect_stress($q$select public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-11T00:00:00Z',null,'Changed','60030000-0000-4000-8000-000000000010',0)$q$,'40001','changed request denied');
select pg_temp.expect_stress($q$select public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-10T00:00:00Z',null,'Stale','60030000-0000-4000-8000-000000000011',0,'{"property":{"id":"hu60-stress-p"},"sourceStress":{"name":"Conservador"},"engine":"test","result":{}}')$q$,'40001','stale version denied');
select pg_temp.expect_stress($q$select public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-11T00:00:00Z','2026-10-11T00:00:00Z','Book','60030000-0000-4000-8000-000000000012',0,'{"property":{"id":"hu60-stress-p"},"sourceStress":{"name":"Conservador"},"engine":"test","result":{}}')$q$,'40001','book version denied');
select pg_temp.expect_stress($q$select public.stress_computed_scenario('60030000-0000-4000-8000-000000000099','hu60-stress-p','2026-10-11T00:00:00Z',null,'Actor','60030000-0000-4000-8000-000000000013',0,'{"property":{"id":"hu60-stress-p"},"sourceStress":{"name":"Conservador"},"engine":"test","result":{}}')$q$,'42501','unknown actor denied');
reset role;
select pg_temp.check_stress((select count(*)=1 from public.analysis_scenarios where property_id='hu60-stress-p') and (select count(*)=1 from public.audit_events where property_id='hu60-stress-p'),'scenario and audit committed once');
create function pg_temp.fail_stress_audit() returns trigger language plpgsql as $$begin if new.property_id='hu60-stress-p' then raise exception using errcode='P0001',message='Synthetic failure';end if;return new;end$$;
create trigger hu60_test_stress_failure before insert on public.audit_events for each row execute function pg_temp.fail_stress_audit();
set local role service_role;
select pg_temp.expect_stress($q$select public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-11T00:00:00Z',null,'Rollback','60030000-0000-4000-8000-000000000014',0,'{"property":{"id":"hu60-stress-p"},"sourceStress":{"name":"Conservador"},"engine":"test","result":{}}')$q$,'P0001','audit failure propagates');
reset role;
select pg_temp.check_stress((select count(*)=1 from public.analysis_scenarios where property_id='hu60-stress-p'),'failed audit rolls back scenario');
select pg_temp.check_stress(not has_table_privilege('service_role','public.analysis_scenarios','insert'),'server has no direct insert grant');
set local role service_role;
select pg_temp.expect_stress($q$select public.stress_computed_scenario('60030000-0000-4000-8000-000000000001','hu60-stress-p','2026-10-11T00:00:00Z',null,'Bad index','60030000-0000-4000-8000-000000000015',6)$q$,'22023','stress index bounded');
rollback;
